// === Audit Task 194: backfill wordEvidence.formType for multi-word surface cells ===
// Auto-tag any cell whose surface contains internal whitespace. 'compound' is the
// default; hello/thanks are 'greeting-formula' / 'thanks-formula'. Auto-tagged
// entries get evidence: 'inferred' so they don't get counted as substantive
// review evidence by the Task 172 reviewStatus heuristic below.
{
    const conceptToFormType = { hello: 'greeting-formula', thanks: 'thanks-formula' };
    for (const code of Object.keys(LANG_DATA)) {
        const lang = LANG_DATA[code];
        if (!lang || !lang.words) continue;
        if (!lang.wordEvidence) lang.wordEvidence = {};
        const we = lang.wordEvidence;
        for (const k of Object.keys(lang.words)) {
            if (we[k] && we[k].formType) continue;  // explicit override wins
            const cell = lang.words[k];
            if (!Array.isArray(cell)) continue;
            const surface = cell[0];
            if (typeof surface !== 'string' || surface === '—') continue;
            if (!/\s/.test(surface)) continue;
            if (!we[k]) we[k] = { evidence: 'inferred', autoTag: 'task-194-multi-word' };
            we[k].formType = conceptToFormType[k] || 'compound';
        }
    }
}

// === Audit Task 172: backfill reviewStatus for all remaining rows ====
// Runs AFTER SOURCE_BACKFILL and Task 194 auto-tagging.
//   - wordEvidence ≥ 5 *substantive* cells AND meta.sources non-empty → 'source-checked'
//   - wordEvidence ≥ 1 substantive cell OR meta.sources non-empty   → 'human-reviewed'
//   - none of the above                                              → 'machine-seeded'
// "Substantive" = not auto-tagged by Task 194 (autoTag flag).
for (const code of Object.keys(LANG_DATA)) {
    const lang = LANG_DATA[code];
    if (!lang || !lang.meta || lang.meta.reviewStatus) continue;
    const we = lang.wordEvidence || {};
    let weCount = 0;
    for (const k of Object.keys(we)) {
        if (we[k] && we[k].autoTag) continue;  // skip auto-tagged formType-only entries
        weCount++;
    }
    const hasSources = lang.meta.sources && lang.meta.sources.length > 0;
    if (weCount >= 5 && hasSources) {
        lang.meta.reviewStatus = 'source-checked';
    } else if (weCount > 0 || hasSources) {
        lang.meta.reviewStatus = 'human-reviewed';
    } else {
        lang.meta.reviewStatus = 'machine-seeded';
    }
}

// === Audit Task 190: backfill meta.vitality from speaker count + dataStatus ===
// Heuristic: extinct/historical/proto rows → 'extinct'; otherwise scale by L1 count.
// Runtime initializer; explicit meta.vitality on a row overrides the heuristic.
{
    const dso = (typeof DATA_STATUS_OVERRIDES !== 'undefined') ? DATA_STATUS_OVERRIDES : {};
    function parseSpeakerCount(s) {
        if (typeof s !== 'string') return null;
        // Prefer a number directly attached to a unit so ranges parse to their upper
        // bound: "~4–5M" → 5M, "~50–80K" → 80K (an en-dash between the low number and
        // the unit otherwise made the low number unit-less, e.g. "4–5M" read as 4).
        // Fall back to the first bare number ("~80 (…)" → 80).
        let m = s.match(/([\d.]+)\s*(K|M|B|million|billion|thousand)\b/i);
        if (!m) m = s.match(/(?:~|≈|<|>|≥|≤)?\s*([\d.]+)/);
        if (!m) return null;
        let n = parseFloat(m[1]);
        if (!Number.isFinite(n)) return null;
        const unit = (m[2] || '').toLowerCase();
        if (unit === 'k' || unit === 'thousand') n *= 1e3;
        else if (unit === 'm' || unit === 'million') n *= 1e6;
        else if (unit === 'b' || unit === 'billion') n *= 1e9;
        return n;
    }
    function vitalityFromCount(n) {
        if (n === null || !Number.isFinite(n)) return 'unknown';
        if (n < 100) return 'critically-endangered';
        if (n < 1000) return 'severely-endangered';
        if (n < 10000) return 'definitely-endangered';
        if (n < 100000) return 'vulnerable';
        return 'safe';
    }
    for (const code of Object.keys(LANG_DATA)) {
        const lang = LANG_DATA[code];
        if (!lang || !lang.meta || lang.meta.vitality) continue;
        const m = lang.meta;
        const status = m.dataStatus || dso[code] || 'modern';
        const sp = (m.speakers || '').toLowerCase();
        if (status !== 'modern') {
            // A 'fragmentary' data status means the WORD DATA is partial, NOT that the
            // language is dead: living-but-under-documented languages (e.g. Itelmen,
            // Tundra Yukaghir, Yaghnobi) get this status yet still have speakers. For
            // those, unless the speaker prose says dead / dormant / zero, fall through
            // to the same count-based derivation used for modern rows. Every other
            // non-modern status (attested/reconstructed/liturgical historical registers)
            // stays 'extinct' as a living vernacular.
            const deadProse = /extinct|dormant|no (?:living|native|fluent|remaining) speakers|^\s*~?0\b/.test(sp);
            if (status !== 'fragmentary' || deadProse) {
                m.vitality = 'extinct';
                continue;
            }
        }
        // Parse speaker count. Look for "extinct" or endangerment prose first.
        if (/extinct/.test(sp)) { m.vitality = 'extinct'; continue; }
        if (/critically endangered/.test(sp)) { m.vitality = 'critically-endangered'; continue; }
        if (/severely endangered/.test(sp)) { m.vitality = 'severely-endangered'; continue; }
        if (/definitely endangered/.test(sp)) { m.vitality = 'definitely-endangered'; continue; }
        if (/vulnerable/.test(sp)) { m.vitality = 'vulnerable'; continue; }
        const n = parseSpeakerCount(m.speakers || '');
        m.vitality = vitalityFromCount(n);
    }
}

// === Audit Task 193: backfill meta.textDirection: 'rtl' for RTL-script rows ===
// Detect RTL by checking if any surface form contains characters from RTL Unicode
// blocks (Hebrew, Arabic, Syriac, Thaana, NKo, Samaritan, Mandaic, Arabic Presentation Forms).
// Set textDirection: 'rtl' so UI rendering can use proper bidi behavior. LTR rows
// remain unset (default 'ltr').
{
    const RTL_RE = /[֐-׿؀-ۿ܀-ݏݐ-ݿހ-޿߀-߿ࠀ-࠿ࡀ-࡟ࢠ-ࣿﭐ-﷿ﹰ-﻿]/;
    for (const code of Object.keys(LANG_DATA)) {
        const lang = LANG_DATA[code];
        if (!lang || !lang.meta || lang.meta.textDirection) continue;
        const w = lang.words || {};
        let isRtl = false;
        for (const k of Object.keys(w)) {
            if (Array.isArray(w[k]) && typeof w[k][0] === 'string' && RTL_RE.test(w[k][0])) { isRtl = true; break; }
        }
        if (isRtl) lang.meta.textDirection = 'rtl';
    }
}

// === Audit Task 162: backfill meta.unattestedReason for all `—` cells ===
// For each `—` cell, set meta.unattestedReason[concept] from defaults if not
// already set. Languages can override via explicit assignment in their meta.
for (const code of Object.keys(LANG_DATA)) {
    const lang = LANG_DATA[code];
    if (!lang || !lang.meta) continue;
    const w = lang.words || {};
    let dashCells = [];
    for (const k of Object.keys(w)) {
        if (Array.isArray(w[k]) && w[k][0] === '—') dashCells.push(k);
    }
    if (dashCells.length === 0) continue;
    if (!lang.meta.unattestedReason) lang.meta.unattestedReason = {};
    for (const concept of dashCells) {
        if (!lang.meta.unattestedReason[concept]) {
            lang.meta.unattestedReason[concept] = UNATTESTED_REASON_DEFAULTS[concept] || 'unknown';
        }
    }
}

// === scriptTags (Audit Task 130) ===================================
// Audit Task 192 (2026-05-07): SCRIPT_TAGS runtime overlay migrated to
// static `meta.scriptTags` fields on the 7 affected meta blocks
// (hak_cn, cdo, ine, sukh, zkt, juc, och). The overlay map and its
// setter loop have been removed. Static grep over wordmap_meta.js now
// returns full coverage of meta.scriptTags directly.

// === Mechanical string→object description migration (Audit Task 145) ===
// Phase A: convert any remaining string descriptions to `{ en: '...' }`
// Phase B: add ja/ko/zh translations for 35 recently-added rows below.
for (const code of Object.keys(LANG_DATA)) {
    const m = LANG_DATA[code] && LANG_DATA[code].meta;
    if (m && typeof m.description === 'string') {
        const en = m.description;
        m.description = { en };
    }
}

// === Phase B: ja/ko/zh translations (Audit Task 145) ===
// Concise translations for 35 rows with English-only descriptions.
const DESC_JKZ = {
    cv:    { ja: 'チュヴァシ語はオグール・テュルク系統の唯一の現存言語で、テュルク語族における最深の分岐を担う。原テュルク語の特徴(ロタチズム r↔z、ラムダチズム l↔š)を保持しており、史的再構の鍵となる。中部ヴォルガ流域のチュヴァシ共和国で話される。', ko: '추바시어는 오구르 튀르크 계열의 유일한 현존 언어로, 튀르크어족 가장 깊은 분기를 담당한다. 원시 튀르크어 특징(로타시즘 r↔z, 람다시즘 l↔š)을 보존하여 역사적 재구의 핵심이다.', zh: '楚瓦什语是奥古尔突厥语支唯一的现存语言，代表突厥语系最深的分裂。保留原始突厥语特征（r↔z 罗塔化、l↔š 兰姆达化），对历史重构至关重要。' },
    dv:    { ja: 'ディベヒ語はモルディブ共和国の公用語で、最南端のインド・アーリア語。18世紀に開発された右横書きのターナ文字で記録され、上半分にアラビア数字、下半分に独自字形を組み合わせる。シンハラ語と異なる島嶼独自の発展を遂げている。', ko: '디베히어는 몰디브 공식 언어이며 가장 남단의 인도아리아어이다. 18세기 개발된 RTL 타나 문자로 기록되며, 상단은 아라비아 숫자, 하단은 고유 문자가 결합한다.', zh: '迪维希语是马尔代夫官方语言，最南端的印度雅利安语。以18世纪发展的从右至左塔纳文字书写，上部为阿拉伯数字、下部为本族文字组合。与僧伽罗语有截然不同的岛屿发展。' },
    azb:   { ja: '南アゼルバイジャン語はイラン北西部で話される、北アゼルバイジャン共和国公用語と密接に関連するテュルク語。話者数 1,300 万以上、ペルシャ語アラビア文字で記録される。', ko: '남아제르바이잔어는 이란 북서부에서 사용되며 북아제르바이잔공화국 공용어와 밀접히 관련된 튀르크어이다. 화자 1,300만+, 아랍 문자 페르시아 변형으로 기록된다.', zh: '南阿塞拜疆语在伊朗西北部使用，与北阿塞拜疆共和国官方语言密切相关，属突厥语。使用波斯阿拉伯文字，使用人口1300万以上。' },
    gag:   { ja: 'ガガウズ語はモルドバ南部の自治区ガガウジアで話されるテュルク系言語。正教徒のガガウズ人の母語で、キリル文字とラテン文字の両方で記録される。', ko: '가가우즈어는 몰도바 남부 가가우지아 자치구역에서 사용되는 튀르크어이다. 정교 신자 가가우즈인의 모어로, 키릴 문자와 라틴 문자 모두로 기록된다.', zh: '加告兹语是摩尔多瓦南部加告兹自治区使用的突厥语。东正教加告兹人的母语，使用西里尔字母和拉丁字母两种文字。' },
    arq:   { ja: 'アルジェリア・アラビア語はマグレブ系アラビア語の代表的方言の一つで、ベルベル系基層と仏語借用語が顕著。話者数 4,000 万以上で、北アフリカで最大規模のアラビア語方言。', ko: '알제리 아랍어는 마그레브 아랍어 대표 방언 중 하나로, 베르베르 기층과 프랑스어 차용이 현저하다. 화자 4,000만+, 북아프리카 최대 아랍어 방언.', zh: '阿尔及利亚阿拉伯语是马格里布阿拉伯语代表方言之一，柏柏尔语底层和法语借词显著。使用人口4000万以上，是北非最大的阿拉伯语方言。' },
    mey:   { ja: 'ハッサニア・アラビア語はモーリタニアの主要言語で、サハラ西部に分布するベドウィン系アラビア語。古典アラビア語の特徴を多く保持しており、アラビア半島起源の遊牧アラブの末裔の言語。', ko: '하사니야 아랍어는 모리타니아 주요 언어로, 서사하라에 분포하는 베두인 계 아랍어. 고전 아랍어 특징을 다수 보존, 아라비아 반도 기원 유목 아랍의 후예 언어.', zh: '哈萨尼亚阿拉伯语是毛里塔尼亚主要语言，分布于西撒哈拉的贝都因系阿拉伯语。保留许多古典阿拉伯语特征，阿拉伯半岛起源游牧阿拉伯人的后裔语言。' },
    en_nz: { ja: 'ニュージーランド英語は前舌母音シフト(KIT/DRESS/TRAP の上昇)、NEAR/SQUARE 統合、マオリ語からの大量借用語(kia ora, whānau, marae 等)が特徴。約 400 万の母語話者。', ko: '뉴질랜드 영어는 전설 모음 상승(KIT/DRESS/TRAP), NEAR/SQUARE 합류, 마오리어 차용어(kia ora, whānau 등) 다수 통합이 특징. 모어 화자 약 400만.', zh: '新西兰英语以前元音上升（KIT/DRESS/TRAP）、NEAR/SQUARE 合并和大量毛利语借词（kia ora, whānau 等）为特征，母语者约400万。' },
    kea:   { ja: 'カーボベルデ・クレオール (Kabuverdianu) は最大規模のポルトガル系クレオール語で、カーボベルデ全土の日常言語。サンティアゴ島基準のソタヴェント方言と、サンビセンテ基準のバルラヴェント方言の二大変種。2009 年にALUPEC正書法が公認。', ko: '카보베르데 크레올어는 최대 규모 포르투갈계 크레올어로, 카보베르데 전역의 일상 언어. 산티아고 기준 소타벤투, 상비센트 기준 바를라벤투의 두 변종. 2009년 ALUPEC 정서법 공인.', zh: '佛得角克里奥尔语是最大的葡萄牙系克里奥尔语，佛得角全境的日常用语。圣地亚哥岛基准的索塔文托与圣维森特岛基准的巴拉文托两大变体。2009 年 ALUPEC 正字法获官方承认。' },
    rmy:   { ja: 'ヴラフ・ロマ語はバルカン半島でルーマニア語・スラヴ語と接触して発達した、最大規模のロマ語方言群。カルデラシュ・ロヴァリ等が主要下位方言。話者数 150 万以上、本ページの形は Kalderash 方言基準。', ko: '블락스 로마니어는 발칸 반도에서 루마니아어·슬라브어와 접촉해 발달한 최대 규모 로마니어 방언군. Kalderash·Lovari 등이 주요 하위 방언. 화자 150만+, 본 페이지 어형은 Kalderash 기준.', zh: '弗拉克斯罗姆语是巴尔干半岛与罗马尼亚语·斯拉夫语接触下发展的最大罗姆语方言群。卡尔德拉什、洛瓦里等为主要下位方言。使用人口 150 万以上，本页词形以卡尔德拉什为基准。' },
    pis:   { ja: 'ピジン語はソロモン諸島の英語ベース・メラネシアン・ピジンで、トク・ピシン (PNG) とビスラマ (バヌアツ) の姉妹言語。三言語で連続体を形成し、共通の核語彙と基層由来文法を共有。', ko: '피진어는 솔로몬 제도의 영어 기반 멜라네시아 피진어로, 톡 피신(PNG)과 비슬라마(바누아투)의 자매 언어. 세 언어가 연속체를 이루며 공통 어휘와 기층 문법을 공유.', zh: '皮金语是所罗门群岛的英语底层美拉尼西亚皮金语，与巴布亚新几内亚的托克皮辛和瓦努阿图的比斯拉马为姊妹语。三者形成连续体，共享核心词汇和底层语法。' },
    sma:   { ja: '南サーミ語はノルウェー・スウェーデン国境地帯のスノーサ周辺で話されるウラル系サーミ語の最南分岐。話者数約 500 で危機言語。北サーミ語と相互不通。', ko: '남사미어는 노르웨이·스웨덴 국경 지대 스노사 인근에서 사용되는 우랄계 사미어 최남단 분기. 화자 약 500명, 위기 언어. 북사미어와 상호 불통.', zh: '南萨米语是挪威·瑞典边境斯诺萨周边使用的乌拉尔系萨米语最南分支。使用者约500人，濒危语言。与北萨米语不能互通。' },
    smj:   { ja: 'ルレ・サーミ語はスウェーデン・ノルレボッテン県と隣接ノルウェー・ノルランで話される。話者数約 2,000、サーミ語族で第二の規模。危機言語だが共同体保護が積極的。', ko: '룰레 사미어는 스웨덴 노르보텐과 인접 노르웨이 노를란에서 사용된다. 화자 약 2,000, 사미어족 중 두 번째 규모. 위기 언어이나 공동체 보호 활발.', zh: '吕勒萨米语在瑞典北博滕省和邻接挪威诺德兰使用。使用者约2,000人，是萨米语族第二大语言。濒危但社群保护活跃。' },
    smn:   { ja: 'イナリ・サーミ語はフィンランド最北部イナリ湖周辺のみで話される。話者数約 400 と極端に少ないが、イマージョン保育所による積極的復興運動が注目される。', ko: '이나리 사미어는 핀란드 최북단 이나리 호 주변에서만 사용. 화자 약 400으로 극히 적으나, 몰입 어린이집 통한 적극적 부흥 운동이 주목.', zh: '伊纳里萨米语仅在芬兰最北端伊纳里湖周边使用。使用者约400人，极少，但通过沉浸式幼儿园的积极复兴运动值得关注。' },
    sms:   { ja: 'スコルト・サーミ語はサーミ伝統居住域がフィンランド・ロシア国境を跨いで広がっていた。第二次大戦後、フィンランド領セヴェッティヤルヴィに移住者が集中。話者数約 300 で危機言語。', ko: '스콜트 사미어는 핀란드·러시아 국경에 걸친 사미 전통 거주지에서 사용되었다. 제2차 세계대전 후 핀란드령 세베티에르비로 이주자 집중. 화자 약 300, 위기 언어.', zh: '斯科尔特萨米语原通行于跨芬兰-俄罗斯边境的萨米传统居住区。二战后移民集中于芬兰境内 Sevettijärvi。使用者约300人，濒危。' },
    vro:   { ja: 'ヴォロ語はエストニア南東部のヴォル周辺で話されるフィン語派の南エストニア群言語。エストニア語と相互理解性は限定的で、独立言語として復興運動が進行中。', ko: '뵈로어는 에스토니아 남동부 뵈루 주변에서 사용되는 핀계 남에스토니아군 언어. 에스토니아어와 상호 이해성 제한적, 독립 언어로 부흥 운동 진행.', zh: '沃罗语是爱沙尼亚东南部沃鲁周边使用的芬兰语支南爱沙尼亚群语言。与爱沙尼亚语相互理解度有限，作为独立语言正进行复兴运动。' },
    vo:    { ja: 'ヴォラピュク (1879) はシュレイヤーが考案、エスペラント (1887) より早く広まった最初の国際補助語。英語・ドイツ語・ラテン語の語根を改変した語彙、格接尾辞・時制・法・相を有する。話者数は現在ごく少数だが、最初期の国際補助語としての歴史的意義は大きい。', ko: '볼라퓌크(1879)는 슐라이어가 고안, 에스페란토(1887)보다 먼저 보급된 최초의 국제보조어. 영·독·라틴어 어근을 개조한 어휘, 격 접미사·시제·법·상을 갖춘다. 현재 화자 극소수, 그러나 첫 IAL로서의 역사적 의의는 크다.', zh: '沃拉普克语 (1879) 由施莱尔创制，比世界语（1887）更早传播，是首个广为接受的国际辅助语。词汇改造自英、德、拉丁语根，具备格后缀、时态、语气、体。今天使用者极少，但作为最早的国际辅助语具有重要的语言史价值。' },
    ia:    { ja: 'インターリングア (1951) はIALAが設計した自然主義的国際補助語。語彙はラテン語・ロマンス諸語の共通根に基づき、英・仏・伊・西・葡語の読者は予習なしに読解可能。エスペラントとは異なり、図式的規則化を行わない哲学。', ko: '인테르링구아(1951)는 IALA가 설계한 자연주의적 국제보조어. 어휘는 라틴어·로망스어 공통 어근에 근거, 영·프·이·스·포 독자가 사전 학습 없이 독해 가능. 에스페란토와 달리 도식적 규칙화를 하지 않는 철학.', zh: '国际语 (1951) 是 IALA 设计的自然主义国际辅助语。词汇基于拉丁语·罗曼语共同词根，英、法、意、西、葡读者无需预习即可阅读。与世界语不同，不采用图式化规则化哲学。' },
    kam:   { ja: 'カンバ語 (Kĩkamba) はケニア東部州の主要バントゥー語で、Bantu E70 系統。話者数約 400 万、キクユ・ルヒヤ・カレンジン・ルオと並ぶケニア五大民族言語の一つ。', ko: '캄바어(Kĩkamba)는 케냐 동부주의 주요 반투어로, Bantu E70 계열. 화자 약 400만, 키쿠유·루히야·칼렌진·루오와 함께 케냐 5대 민족 언어 중 하나.', zh: '坎巴语 (Kĩkamba) 是肯尼亚东部省的主要班图语，属 Bantu E70 系。使用人口约400万，与基库尤、卢希亚、卡伦金、卢奥并列肯尼亚五大民族语言。' },
    ses:   { ja: 'コイラボロ・センニ (東ソンガイ語) は中世サヘル交易の中心地ガオ・トンブクトゥの言語。ソンガイ語族はアフリカ内で系統孤立的(ナイル・サハラとも分類されるが、独立分類が有力)。', ko: '코이라보로 센니(동부 송하이어)는 중세 사헬 교역 중심지 가오·팀북투의 언어. 송하이어족은 아프리카 내에서 계통 고립적(나일-사하라로 분류되기도 하나 독립 분류가 유력).', zh: '科伊拉博罗森尼（东桑海语）是中世纪萨赫勒贸易中心加奥和廷巴克图的语言。桑海语族在非洲内部属系统孤立（虽有归入尼罗-撒哈拉的说法，但独立分类更受支持）。' },
    tzh:   { ja: 'ツェルタル語はチアパス高原のマヤ語族チョラン・ツェルタラン分岐で、ツォツィル語の姉妹語。L1 話者数では Yucatec を除きメキシコ最大のマヤ系言語。', ko: '첼탈어는 치아파스 고원의 마야어족 촐란-첼탈란 분기로, 초칠어의 자매 언어. L1 화자 수에서는 유카텍을 제외한 멕시코 최대 마야계 언어.', zh: '泽塔尔语是恰帕斯高地的玛雅语族乔兰-泽塔兰分支，与佐齐尔语为姊妹语。除尤卡特克语外，是墨西哥按 L1 使用人口最大的玛雅系语言。' },
    kpv:   { ja: 'コミ・ジリエン (Komi-Zyrian) はロシア北西部コミ共和国の主要なペルム系ウラル語。マクロ言語コード `kv` (Komi) が指す主要な変種。コミ・ペルミャクとともにウドムルトと並ぶペルム分岐を構成。', ko: '코미지리안어는 러시아 북서부 코미 공화국의 주요 페름계 우랄어. 매크로 언어 코드 `kv`(Komi)가 가리키는 주요 변종. 코미페르먀크와 함께 우드무르트와 나란히 페름 분기를 구성.', zh: '科米-济良语是俄罗斯西北部科米共和国的主要彼尔米语支乌拉尔语。宏语言代码 `kv`（Komi）实际指向此变体。与科米-彼尔米亚克并列彼尔米分支，与乌德穆尔特并列。' },
    koi:   { ja: 'コミ・ペルミャク語はロシアのペルミ地方コミ・ペルミャク管区のペルム系ウラル語。コミ・ジリエンと近縁だが別言語として分類される。', ko: '코미페르먀크어는 러시아 페름 지방 코미페르먀크 관구의 페름계 우랄어. 코미지리안과 가깝지만 별개 언어로 분류된다.', zh: '科米-彼尔米亚克语是俄罗斯彼尔姆边疆区科米-彼尔米亚克自治区的彼尔米语支乌拉尔语。与科米-济良关系密切但归类为独立语言。' },
    mdf:   { ja: 'モクシャ語はモルドヴィン系ウラル語の二大言語の一つ (もう一つはエルジャ語)。モルドヴィア共和国の公用語の一つだが、エルジャ語とは相互理解性なし。話者数約 25 万、モルドヴィア南部・西部に分布。', ko: '목샤어는 모르드빈계 우랄어 양대 언어 중 하나(다른 하나는 에르자어). 모르도비아 공화국 공용어이나 에르자어와 상호 불통. 화자 약 25만, 모르도비아 남부·서부 분포.', zh: '莫克沙语是莫尔多温乌拉尔语两大语言之一（另一为厄尔兹亚语）。莫尔多瓦共和国官方语言之一，但与厄尔兹亚语不能互通。使用人口约 25 万，分布于莫尔多瓦南部和西部。' },
    vep:   { ja: 'ヴェプス語はロシア北西部のバルト・フィン系ウラル語で、危機言語の代表例として言語学的に注目される。フィン語・カレリア語・エストニア語と近縁。話者数約 1,600。', ko: '베프스어는 러시아 북서부 발토핀계 우랄어로, 위기 언어 사례로 언어학적 주목을 받는다. 핀란드어·카렐리야어·에스토니아어와 가깝다. 화자 약 1,600.', zh: '维普森语是俄罗斯西北部波罗的海芬兰系乌拉尔语，作为濒危语言案例在语言学界备受关注。与芬兰语、卡累利阿语、爱沙尼亚语近缘。使用者约1,600人。' },
    vot:   { ja: 'ヴォート語 (Votic) は近絶滅状態のバルト・フィン系言語で、エストニア語に最も近縁。流暢話者数は十数人前後で、エストニア・ロシア国境の二村に集中。古層特徴の保存により言語学的に重要。', ko: '보트어는 근절멸 상태의 발토핀계 언어로, 에스토니아어와 가장 가깝다. 유창 화자 십수 명, 에스토니아·러시아 국경 두 마을에 집중. 고층 특징 보존으로 언어학적으로 중요.', zh: '沃特语处于濒灭绝状态，属波罗的海芬兰语支，与爱沙尼亚语最为近缘。流利使用者约十余人，集中于爱沙尼亚-俄罗斯边境两村。因保留古层特征而具语言学价值。' },
    cgg:   { ja: 'チガ語 (Rukiga) はウガンダ南西部のバントゥー JE 系統言語で、ニャンコレ・トーロ・ニョロと共にルニャキタラ・クラスタを形成。相互理解性が高い。', ko: '치가어(Rukiga)는 우간다 남서부 반투 JE 계열 언어로, 뉴완콜레·토로·뇨로와 함께 루냐키타라 클러스터 형성. 상호 이해성 높음.', zh: '奇加语 (Rukiga) 是乌干达西南部的 Bantu JE 系语言，与尼安科莱、托罗、尼奥罗共同构成 Runyakitara 集群。相互可懂度很高。' },
    ttj:   { ja: 'トーロ語 (Rutooro) はウガンダ西部のバントゥー JE 系統で、ニョロ語と Swadesh レベルでほぼ同一(両者を Rutooro-Runyoro として一語扱いする立場もある)。', ko: '토로어(Rutooro)는 우간다 서부 반투 JE 계열로, 뇨로어와 Swadesh 수준에서 거의 동일(둘을 Rutooro-Runyoro로 단일 언어 취급하기도 함).', zh: '托罗语 (Rutooro) 是乌干达西部 Bantu JE 系，与尼奥罗语在 Swadesh 层面几乎相同（两者有时被合称 Rutooro-Runyoro 视为同一语言）。' },
    nyo:   { ja: 'ニョロ語 (Runyoro) はウガンダ西部の Bantu JE 系言語で、歴史的なブニョロ王国の主要言語。トーロ語と Runyoro-Rutooro ペアを形成。', ko: '뇨로어(Runyoro)는 우간다 서부 Bantu JE 계 언어로, 역사적인 부뇨로 왕국의 주요 언어. 토로어와 Runyoro-Rutooro 짝을 형성.', zh: '尼奥罗语 (Runyoro) 是乌干达西部 Bantu JE 系语言，历史上布尼奥罗王国的主要语言。与托罗语形成 Runyoro-Rutooro 配对。' },
    tem:   { ja: 'テムネ語 (KʌThemnɛ) はシエラレオネ二大言語の一つで、メンデ語と並ぶ。アトランティック・コンゴ語族メル分岐に属し、文法的名詞クラス体系を持つ。', ko: '템네어(KʌThemnɛ)는 시에라리온 양대 언어 중 하나로, 멘데어와 어깨를 나란히 한다. 아틀란틱-콩고어족 멜 분기 소속, 문법적 명사 부류 체계를 가진다.', zh: '泰姆奈语 (KʌThemnɛ) 是塞拉利昂两大语言之一，与门德语并列。属大西洋-刚果语族梅尔分支，具备语法名词类系统。' },
    tmh:   { ja: 'タマシェク語はベルベル系の主要言語で、サハラ・サヘル地帯のトゥアレグ族の言語。マリ・ニジェール・アルジェリア・リビア・ブルキナファソに分布。歴史的にはティフィナグ文字で記録される。', ko: '타마섹어는 베르베르 계열 주요 언어로, 사하라·사헬 지대 투아레그족의 언어. 말리·니제르·알제리·리비아·부르키나파소에 분포. 역사적으로 티피나그 문자로 기록.', zh: '塔马舍克语是柏柏尔语支主要语言，撒哈拉和萨赫勒地带图阿雷格族的语言。分布于马里、尼日尔、阿尔及利亚、利比亚、布基纳法索。历史上以提非纳格文字书写。' },
    rcf:   { ja: 'レユニオン・クレオール (Kreol Réyoné) はインド洋レユニオン島で話されるフランス語ベース・クレオール。話者数約 60 万、東アフリカ・バントゥー語およびマダガスカル語の基層影響あり。', ko: '레위니옹 크레올어(Kreol Réyoné)는 인도양 레위니옹 섬에서 사용되는 프랑스어 기반 크레올. 화자 약 60만, 동아프리카 반투어 및 말라가시어 기층 영향 있음.', zh: '留尼汪克里奥尔语 (Kreol Réyoné) 是印度洋留尼汪岛的法语底层克里奥尔语。使用者约60万人，受东非班图语和马达加斯加语底层影响。' },
    crs:   { ja: 'セーシェル・クレオール (Kreol Seselwa) はセーシェル共和国の公用語で、フランス語ベース・クレオール。モーリシャス・レユニオンと並んで、インド洋フランス系クレオール三種を構成する。', ko: '세이셸 크레올어(Kreol Seselwa)는 세이셸 공식 언어로, 프랑스어 기반 크레올. 모리셔스·레위니옹과 함께 인도양 프랑스계 크레올 삼종을 구성.', zh: '塞舌尔克里奥尔语 (Kreol Seselwa) 是塞舌尔官方语言，法语底层克里奥尔语。与毛里求斯、留尼汪共同构成印度洋法系克里奥尔三种。' },
    gcf:   { ja: 'グアドループ・クレオール (Kréyòl Gwadloupéyen) はフランス領グアドループのフランス語ベース・クレオール。マルティニーク・クレオールと近縁で、奴隷貿易期に西アフリカ諸語の基層影響を受けた。', ko: '과들루프 크레올어(Kréyòl Gwadloupéyen)는 프랑스령 과들루프의 프랑스어 기반 크레올. 마르티니크 크레올과 가깝고, 노예 무역기 서아프리카 언어 기층 영향 받음.', zh: '瓜德罗普克里奥尔语 (Kréyòl Gwadloupéyen) 是法属瓜德罗普的法语底层克里奥尔语。与马提尼克克里奥尔近缘，奴隶贸易时期受西非语言底层影响。' },
    laj:   { ja: 'ランゴ語 (Lëblaŋo) はウガンダ北部リラ周辺で話される西ナイル語族ルウォー分岐の言語。アチョリ語の姉妹語で、より遠くケニアのルオ語と関連。話者数約 210 万。', ko: '랑고어(Lëblaŋo)는 우간다 북부 리라 인근에서 사용되는 서나일계 Lwoo 분기 언어. 아촐리어의 자매 언어이며, 더 멀리 케냐 루오어와 관련. 화자 약 210만.', zh: '兰戈语 (Lëblaŋo) 是乌干达北部利拉周边使用的西尼罗-Lwoo 分支语言。与阿乔利语为姊妹语，更远与肯尼亚的卢奥语相关。使用者约210万。' },
    byn:   { ja: 'ブリン語 (ビレン) はエリトリアで話される唯一のクシ系アガウ分岐言語。ケレンを中心に話され、ティグリニャ・ティグレ・サホ・アファルと共にエリトリア言語景観を構成。ゲエズ文字とラテン文字併用。', ko: '블린어(빌렌)는 에리트리아에서 사용되는 유일한 쿠시계 아가우 분기 언어. 케렌 중심으로 사용되며, 티그리냐·티그레·사호·아파르와 함께 에리트리아 언어 경관을 구성. 게에즈 문자와 라틴 문자 병용.', zh: '布林语（比林语）是厄立特里亚使用的唯一库什语支阿高分支语言。以凯伦为中心使用，与提格利尼亚、提格雷、萨霍、阿法尔共同构成厄立特里亚语言景观。同时使用吉兹文字和拉丁字母。' },
};
for (const code of Object.keys(DESC_JKZ)) {
    const m = LANG_DATA[code] && LANG_DATA[code].meta;
    if (!m || typeof m.description !== 'object') continue;
    for (const ui of ['ja', 'ko', 'zh']) {
        if (DESC_JKZ[code][ui] && m.description[ui] === undefined) {
            m.description[ui] = DESC_JKZ[code][ui];
        }
    }
}

// === Surface dataStatus into meta (per wordmap-check-2.md §C4) ===
// Copy explicit DATA_STATUS_OVERRIDES (defined in wordmap_data.js) into
// each language's meta so validators and downstream consumers can read it
// from a single canonical place. wordmap.html's getDataStatus() still
// auto-derives 'fragmentary' for historical langs not listed here.
if (typeof DATA_STATUS_OVERRIDES !== 'undefined') {
    for (const code of Object.keys(DATA_STATUS_OVERRIDES)) {
        if (LANG_DATA[code] && LANG_DATA[code].meta) {
            LANG_DATA[code].meta.dataStatus = DATA_STATUS_OVERRIDES[code];
        }
    }
}

// Cia-Cia (cia) — added 2026-07-09. Word data from two independent researchers
// (Mead 2017 Wasambua wordlist; en/id Wiktionary Cia-Cia lemmas; Omniglot;
// van den Berg 1991) with an adjudication pass; see wordmap_reviews/review_410_closed.md.
LANG_DATA['cia'] && (LANG_DATA['cia'].meta = {
    family: 'Austronesian (Malayo-Polynesian, Celebic, Muna-Buton)',
    speakers: '~80–105K (Ethnologue 6b: threatened)',
    countries: 'Indonesia (Southeast Sulawesi — southern Buton Island, Binongko, Batu Atas)',
    official: 'None; a regional vernacular. Indonesian is the official language of the area',
    script: 'Latin; Hangul taught in a few Baubau schools since 2009 (unofficial); formerly the Arabic-derived Gundhul script',
    scriptTags: ['Latin'],
    description:{en:"Cia-Cia (Bahasa Ciacia, also South Buton) is an Austronesian language of the Muna-Buton subgroup, spoken by roughly 80,000–105,000 people around the city of Baubau on southern Buton Island in Southeast Sulawesi, Indonesia. Phonologically it is typical of the region: five vowels, a phonemic glottal stop (written with an apostrophe, as in ka'ana 'house' and we'e 'water'), a series of prenasalized stops, and the implosives /ɓ/ and /ɗ/ that ordinary Latin spelling under-transcribes as plain b and d. The language became internationally famous in 2009, when Baubau began teaching it in the Korean Hangul script — reviving obsolete jamo such as ᄫ for the bilabial fricative Korean lacks. That project has always been far smaller than its fame: Hangul is used in the schools and street signs of a couple of subdistricts, never officially adopted, and the overwhelming majority of Cia-Cia writing is still Latin. Most speakers are bilingual in Indonesian and many also use the closely related Wolio.",ja:"チアチア語（Bahasa Ciacia、南ブトン語）は、インドネシア南東スラウェシ州ブトン島南部のバウバウ市周辺で約8万〜10万5千人が話すオーストロネシア語族ムナ・ブトン語群の言語である。音韻的には地域の典型で、5母音、音素としての声門閉鎖音（ka'ana「家」、we'e「水」のようにアポストロフィで表記）、前鼻音化閉鎖音の系列、そして通常のラテン文字表記では単なる b・d と書かれてしまう入破音 /ɓ/ /ɗ/ を持つ。2009年、バウバウ市がこの言語をハングルで教え始めたことで国際的に有名になった。韓国語にない両唇摩擦音のために廃字となった字母 ᄫ を復活させるなどの工夫がなされている。ただし実態は名声よりはるかに小規模で、ハングルが使われるのは数か所の地区の学校と街路標識に限られ、公式に採用されたことはなく、チアチア語の表記の圧倒的多数は今もラテン文字である。話者の多くはインドネシア語との二言語話者であり、近縁のウォリオ語も用いる。",ko:"찌아찌아어(Bahasa Ciacia, 남부 부톤어)는 인도네시아 남동술라웨시주 부톤섬 남부의 바우바우시 일대에서 약 8만~10만 5천 명이 사용하는 오스트로네시아어족 무나-부톤어군의 언어이다. 음운적으로는 이 지역의 전형으로, 다섯 개의 모음, 음소로서의 성문 폐쇄음(ka'ana '집', we'e '물'처럼 아포스트로피로 표기), 선비음화 폐쇄음 계열, 그리고 보통의 로마자 표기가 단순한 b·d로 적어 버리는 내파음 /ɓ/·/ɗ/를 지닌다. 2009년 바우바우시가 이 언어를 한글로 가르치기 시작하면서 국제적으로 유명해졌으며, 한국어에 없는 양순 마찰음을 위해 옛 자모 ᄫ을 되살리는 등의 방안이 쓰였다. 다만 실제 규모는 명성보다 훨씬 작아 한글은 몇몇 지구의 학교와 거리 표지판에 쓰일 뿐 공식 문자로 채택된 적이 없고, 찌아찌아어 표기의 절대다수는 여전히 로마자이다. 화자 대부분은 인도네시아어와의 이중언어 사용자이며, 가까운 친척인 월리오어도 함께 쓴다.",zh:"吉阿吉阿语（Bahasa Ciacia，又称南布顿语）属南岛语系穆纳—布顿语群，使用者约8万至10万5千人，分布于印度尼西亚东南苏拉威西省布顿岛南部的巴务巴务市一带。其音系为该地区所典型：五个元音、作为音位的喉塞音（以撇号书写，如 ka'ana「房子」、we'e「水」）、一整套前鼻化塞音，以及普通拉丁字母拼写只写作 b、d 的内爆音 /ɓ/、/ɗ/。2009年巴务巴务市开始用韩文谚文教授该语言，使其闻名于世；为标注韩语所无的双唇擦音，还复活了废弃字母 ᄫ。然而实况远小于其名声：谚文仅用于少数几个区的学校与路牌，从未被正式采用，吉阿吉阿语的书写绝大多数仍使用拉丁字母。多数使用者兼通印度尼西亚语，许多人也使用近亲的沃利奥语。",yue:"吉阿吉阿語（Bahasa Ciacia，又稱南布頓語）屬南島語系穆納—布頓語群，使用者約8萬至10萬5千人，分佈喺印尼東南蘇拉威西省布頓島南部嘅巴務巴務市一帶。佢嘅音系係呢個地區嘅典型：五個元音、作為音位嘅喉塞音（用撇號寫，好似 ka'ana「屋」、we'e「水」）、一整套前鼻化塞音，同埋普通拉丁字母只寫作 b、d 嘅內爆音 /ɓ/、/ɗ/。2009年巴務巴務市開始用韓文諺文教呢種語言，令佢揚名國際；為咗標注韓語冇嘅雙唇擦音，仲復活咗廢棄字母 ᄫ。不過實情遠細過佢嘅名聲：諺文淨係用喺少數幾個區嘅學校同路牌，從來冇正式採用，吉阿吉阿語嘅書寫絕大多數仍然用拉丁字母。多數使用者兼通印尼語，好多人亦都用近親嘅沃利奧語。",vi:"Tiếng Cia-Cia (Bahasa Ciacia, còn gọi là tiếng Nam Buton) là một ngôn ngữ Nam Đảo thuộc nhóm Muna-Buton, được khoảng 80.000–105.000 người sử dụng quanh thành phố Baubau ở phía nam đảo Buton, tỉnh Đông Nam Sulawesi, Indonesia. Về mặt âm vị học, nó tiêu biểu cho khu vực này: năm nguyên âm, một âm tắc thanh hầu mang tính âm vị (viết bằng dấu nháy đơn, như trong ka'ana 'nhà' và we'e 'nước'), một loạt phụ âm tắc tiền mũi hóa, và các âm nổ vào /ɓ/ và /ɗ/ mà chữ Latinh thông thường chỉ ghi đơn giản là b và d. Ngôn ngữ này trở nên nổi tiếng khắp thế giới vào năm 2009, khi Baubau bắt đầu dạy nó bằng chữ Hangul của Hàn Quốc — làm sống lại những jamo đã lỗi thời như ᄫ để ghi âm xát hai môi mà tiếng Hàn không có. Dự án ấy luôn nhỏ hơn nhiều so với danh tiếng của nó: Hangul chỉ được dùng trong trường học và biển chỉ đường của một vài phân khu, chưa bao giờ được chính thức áp dụng, và tuyệt đại đa số văn bản tiếng Cia-Cia vẫn viết bằng chữ Latinh. Phần lớn người nói song ngữ với tiếng Indonesia và nhiều người còn dùng tiếng Wolio có quan hệ họ hàng gần.",th:"ภาษาเจียเจีย (Bahasa Ciacia หรือภาษาบูตนใต้) เป็นภาษาตระกูลออสโตรนีเซียนในกลุ่มย่อยมูนา-บูตน มีผู้พูดราว 80,000–105,000 คนบริเวณเมืองเบาเบาทางตอนใต้ของเกาะบูตนในจังหวัดซูลาเวซีตะวันออกเฉียงใต้ ประเทศอินโดนีเซีย ในทางเสียงวิทยาถือว่าเป็นแบบฉบับของภูมิภาคนี้ คือ สระห้าเสียง เสียงกักที่เส้นเสียงซึ่งเป็นหน่วยเสียง (เขียนด้วยเครื่องหมายอะพอสทรอฟี เช่นใน ka'ana 'บ้าน' และ we'e 'น้ำ') ชุดเสียงกักที่มีเสียงนาสิกนำ และเสียงระเบิดเข้า /ɓ/ กับ /ɗ/ ที่การสะกดด้วยอักษรละตินทั่วไปเขียนเพียงเป็น b และ d ภาษานี้มีชื่อเสียงไปทั่วโลกในปี 2009 เมื่อเบาเบาเริ่มสอนภาษานี้ด้วยอักษรฮันกึลของเกาหลี โดยฟื้นชามอที่เลิกใช้แล้วอย่าง ᄫ ขึ้นมาใช้แทนเสียงเสียดแทรกริมฝีปากทั้งสองที่ภาษาเกาหลีไม่มี โครงการนี้เล็กกว่าชื่อเสียงของมันมากมาโดยตลอด อักษรฮันกึลถูกใช้เพียงในโรงเรียนและป้ายถนนของไม่กี่ตำบลย่อยเท่านั้น ไม่เคยได้รับการรับรองอย่างเป็นทางการ และงานเขียนภาษาเจียเจียส่วนใหญ่อย่างท่วมท้นยังคงใช้อักษรละติน ผู้พูดส่วนใหญ่ใช้สองภาษาควบคู่กับภาษาอินโดนีเซีย และหลายคนยังใช้ภาษาโวลิโอที่เป็นญาติใกล้ชิดด้วย",id:"Bahasa Cia-Cia (Bahasa Ciacia, disebut juga Buton Selatan) adalah bahasa Austronesia dari subkelompok Muna-Buton, dituturkan oleh sekitar 80.000–105.000 orang di sekitar kota Baubau di bagian selatan Pulau Buton, Sulawesi Tenggara, Indonesia. Secara fonologis bahasa ini khas untuk kawasan tersebut: lima vokal, hentian glotal fonemis (ditulis dengan tanda apostrof, seperti pada ka'ana 'rumah' dan we'e 'air'), sederet konsonan hambat pranasal, serta konsonan implosif /ɓ/ dan /ɗ/ yang oleh ejaan Latin biasa hanya dituliskan sebagai b dan d. Bahasa ini menjadi terkenal di seluruh dunia pada tahun 2009, ketika Baubau mulai mengajarkannya dengan aksara Hangul Korea — menghidupkan kembali jamo usang seperti ᄫ untuk frikatif bilabial yang tidak dimiliki bahasa Korea. Proyek itu selalu jauh lebih kecil daripada ketenarannya: Hangul hanya dipakai di sekolah dan papan nama jalan beberapa kecamatan, tidak pernah diadopsi secara resmi, dan sebagian besar tulisan Cia-Cia tetap beraksara Latin. Sebagian besar penuturnya dwibahasa dengan bahasa Indonesia dan banyak pula yang memakai bahasa Wolio yang berkerabat dekat.",hi:"चिया-चिया (Bahasa Ciacia, जिसे दक्षिण बूटन भी कहते हैं) मूना-बूटन उपसमूह की एक ऑस्ट्रोनेशियाई भाषा है, जिसे इंडोनेशिया के दक्षिण-पूर्वी सुलावेसी में बूटन द्वीप के दक्षिणी भाग में बाउबाउ शहर के आसपास लगभग 80,000–105,000 लोग बोलते हैं। ध्वनिविज्ञान की दृष्टि से यह इस क्षेत्र के लिए विशिष्ट है: पाँच स्वर, एक स्वनिमिक कंठ्य स्पर्श (एपॉस्ट्रॉफी से लिखा जाता है, जैसे ka'ana 'घर' और we'e 'पानी' में), पूर्व-नासिक्य स्पर्श व्यंजनों की एक शृंखला, और अंतःस्फोटी /ɓ/ तथा /ɗ/ जिन्हें सामान्य लातिन वर्तनी केवल b और d के रूप में लिखकर अधूरा दर्शाती है। यह भाषा 2009 में अंतरराष्ट्रीय स्तर पर प्रसिद्ध हुई, जब बाउबाउ ने इसे कोरियाई हांगुल लिपि में पढ़ाना शुरू किया — कोरियाई में अनुपस्थित द्वयोष्ठ्य संघर्षी ध्वनि के लिए ᄫ जैसे अप्रचलित जामो को पुनर्जीवित करते हुए। यह परियोजना हमेशा अपनी प्रसिद्धि से कहीं छोटी रही है: हांगुल केवल कुछ उप-जिलों के स्कूलों और सड़क-चिह्नों में प्रयुक्त होती है, इसे कभी आधिकारिक रूप से नहीं अपनाया गया, और चिया-चिया लेखन का अत्यधिक बहुमत आज भी लातिन में ही है। अधिकांश वक्ता इंडोनेशियाई के साथ द्विभाषी हैं और बहुत से लोग निकट-संबंधी वोलियो भाषा भी बोलते हैं।",de:"Cia-Cia (Bahasa Ciacia, auch Süd-Buton) ist eine austronesische Sprache der Muna-Buton-Untergruppe, die von etwa 80.000 bis 105.000 Menschen rund um die Stadt Baubau im Süden der Insel Buton in Südost-Sulawesi, Indonesien, gesprochen wird. Phonologisch ist sie typisch für die Region: fünf Vokale, ein phonemischer glottaler Verschlusslaut (mit einem Apostroph geschrieben, wie in ka'ana 'Haus' und we'e 'Wasser'), eine Reihe pränasalierter Verschlusslaute sowie die Implosive /ɓ/ und /ɗ/, die die gewöhnliche lateinische Schreibung nur als schlichtes b und d wiedergibt. Internationale Bekanntheit erlangte die Sprache 2009, als Baubau begann, sie in der koreanischen Hangul-Schrift zu unterrichten — wobei veraltete Jamo wie ᄫ für den bilabialen Frikativ wiederbelebt wurden, den das Koreanische nicht kennt. Dieses Projekt war stets weit kleiner als sein Ruhm: Hangul wird nur in den Schulen und auf Straßenschildern einiger weniger Unterbezirke verwendet, wurde nie offiziell eingeführt, und die überwältigende Mehrheit der Cia-Cia-Texte ist nach wie vor lateinisch geschrieben. Die meisten Sprecher sind zweisprachig mit Indonesisch, und viele verwenden auch das eng verwandte Wolio.",fr:"Le cia-cia (Bahasa Ciacia, aussi appelé bouton du Sud) est une langue austronésienne du sous-groupe muna-buton, parlée par environ 80 000 à 105 000 personnes autour de la ville de Baubau, dans le sud de l’île de Buton, au Sulawesi du Sud-Est, en Indonésie. Sur le plan phonologique, elle est typique de la région : cinq voyelles, une occlusive glottale phonémique (notée par une apostrophe, comme dans ka'ana 'maison' et we'e 'eau'), une série d’occlusives prénasalisées et les implosives /ɓ/ et /ɗ/ que l’orthographe latine ordinaire ne rend que par un simple b et d. La langue est devenue mondialement célèbre en 2009, lorsque Baubau a commencé à l’enseigner dans l’écriture coréenne hangul — ressuscitant des jamo obsolètes comme ᄫ pour la fricative bilabiale qui manque au coréen. Ce projet a toujours été bien plus modeste que sa renommée : le hangul n’est utilisé que dans les écoles et sur les panneaux de rue de quelques sous-districts, n’a jamais été officiellement adopté, et l’écrasante majorité des écrits en cia-cia reste en alphabet latin. La plupart des locuteurs sont bilingues en indonésien et beaucoup utilisent aussi le wolio, langue étroitement apparentée.",it:"Il cia-cia (Bahasa Ciacia, detto anche buton meridionale) è una lingua austronesiana del sottogruppo muna-buton, parlata da circa 80.000–105.000 persone intorno alla città di Baubau, nella parte meridionale dell’isola di Buton, nel Sulawesi Sud-Orientale, in Indonesia. Dal punto di vista fonologico è tipica della regione: cinque vocali, un’occlusiva glottidale fonematica (scritta con un apostrofo, come in ka'ana 'casa' e we'e 'acqua'), una serie di occlusive prenasalizzate e le implosive /ɓ/ e /ɗ/ che l’ortografia latina ordinaria rende soltanto come una semplice b e d. La lingua divenne famosa a livello internazionale nel 2009, quando Baubau iniziò a insegnarla nella scrittura coreana hangul — riportando in vita jamo obsoleti come ᄫ per la fricativa bilabiale che il coreano non possiede. Quel progetto è sempre stato molto più piccolo della sua fama: l’hangul è usato solo nelle scuole e nei cartelli stradali di un paio di sottodistretti, non è mai stato adottato ufficialmente e la stragrande maggioranza degli scritti in cia-cia è tuttora in alfabeto latino. La maggior parte dei parlanti è bilingue con l’indonesiano e molti usano anche il wolio, lingua strettamente imparentata.",es:"El cia-cia (Bahasa Ciacia, también llamado butón meridional) es una lengua austronesia del subgrupo muna-butón, hablada por unas 80.000 a 105.000 personas en torno a la ciudad de Baubau, en el sur de la isla de Butón, en Sulawesi Suroriental, Indonesia. Fonológicamente es típica de la región: cinco vocales, una oclusiva glotal fonémica (escrita con apóstrofo, como en ka'ana 'casa' y we'e 'agua'), una serie de oclusivas prenasalizadas y las implosivas /ɓ/ y /ɗ/ que la ortografía latina corriente apenas transcribe como simples b y d. La lengua se hizo mundialmente famosa en 2009, cuando Baubau empezó a enseñarla en la escritura coreana hangul, recuperando jamos en desuso como ᄫ para la fricativa bilabial de la que carece el coreano. Ese proyecto siempre ha sido mucho más pequeño que su fama: el hangul se usa solo en las escuelas y en los carteles de las calles de un par de subdistritos, nunca se ha adoptado oficialmente y la inmensa mayoría de la escritura en cia-cia sigue siendo en alfabeto latino. La mayoría de los hablantes son bilingües en indonesio y muchos emplean también el wolio, lengua estrechamente emparentada.",pt:"O cia-cia (Bahasa Ciacia, também chamado butão do Sul) é uma língua austronésia do subgrupo muna-butão, falada por cerca de 80 000 a 105 000 pessoas em torno da cidade de Baubau, no sul da ilha de Butão, em Celebes do Sudeste, na Indonésia. Do ponto de vista fonológico é típica da região: cinco vogais, uma oclusiva glotal fonémica (escrita com apóstrofo, como em ka'ana 'casa' e we'e 'água'), uma série de oclusivas pré-nasalizadas e as implosivas /ɓ/ e /ɗ/ que a ortografia latina corrente apenas transcreve como simples b e d. A língua tornou-se mundialmente famosa em 2009, quando Baubau começou a ensiná-la na escrita coreana hangul, ressuscitando jamos obsoletos como ᄫ para a fricativa bilabial que falta ao coreano. Esse projeto sempre foi muito mais pequeno do que a sua fama: o hangul é usado apenas nas escolas e nas placas de rua de umas poucas subdivisões, nunca foi oficialmente adotado, e a esmagadora maioria da escrita em cia-cia continua a ser em alfabeto latino. A maioria dos falantes é bilingue em indonésio e muitos usam também o wólio, língua estreitamente aparentada.",es_eu:"El cia-cia (Bahasa Ciacia, también llamado butón meridional) es una lengua austronesia del subgrupo muna-butón, hablada por unas 80.000 a 105.000 personas en torno a la ciudad de Baubau, en el sur de la isla de Butón, en Sulawesi Suroriental, Indonesia. Fonológicamente es típica de la región: cinco vocales, una oclusiva glotal fonémica (escrita con apóstrofo, como en ka'ana 'casa' y we'e 'agua'), una serie de oclusivas prenasalizadas y las implosivas /ɓ/ y /ɗ/ que la ortografía latina corriente apenas transcribe como simples b y d. La lengua se hizo mundialmente famosa en 2009, cuando Baubau empezó a enseñarla en la escritura coreana hangul, recuperando jamos en desuso como ᄫ para la fricativa bilabial de la que carece el coreano. Ese proyecto siempre ha sido mucho más pequeño que su fama: el hangul se usa solo en las escuelas y en los carteles de las calles de un par de subdistritos, nunca se ha adoptado oficialmente y la inmensa mayoría de la escritura en cia-cia sigue siendo en alfabeto latino. La mayoría de los hablantes son bilingües en indonesio y muchos emplean también el wolio, lengua estrechamente emparentada.",es_mx:"El cia-cia (Bahasa Ciacia, también llamado butón meridional) es una lengua austronesia del subgrupo muna-butón, hablada por alrededor de 80,000 a 105,000 personas en torno a la ciudad de Baubau, en el sur de la isla de Butón, en Sulawesi Suroriental, Indonesia. Fonológicamente es típica de la región: cinco vocales, una oclusiva glotal fonémica (escrita con apóstrofo, como en ka'ana 'casa' y we'e 'agua'), una serie de oclusivas prenasalizadas y las implosivas /ɓ/ y /ɗ/ que la ortografía latina común apenas transcribe como simples b y d. La lengua se volvió mundialmente famosa en 2009, cuando Baubau comenzó a enseñarla en la escritura coreana hangul, recuperando jamos en desuso como ᄫ para la fricativa bilabial de la que carece el coreano. Ese proyecto siempre ha sido mucho más pequeño que su fama: el hangul se usa solo en las escuelas y en los letreros de las calles de un par de subdistritos, nunca se ha adoptado oficialmente y la inmensa mayoría de la escritura en cia-cia sigue siendo en alfabeto latino. La mayoría de los hablantes son bilingües en indonesio y muchos usan también el wolio, lengua estrechamente emparentada.",pt_eu:"O cia-cia (Bahasa Ciacia, também chamado butão do Sul) é uma língua austronésia do subgrupo muna-butão, falada por cerca de 80 000 a 105 000 pessoas em torno da cidade de Baubau, no sul da ilha de Butão, em Celebes do Sudeste, na Indonésia. Do ponto de vista fonológico é típica da região: cinco vogais, uma oclusiva glotal fonémica (escrita com apóstrofo, como em ka'ana 'casa' e we'e 'água'), uma série de oclusivas pré-nasalizadas e as implosivas /ɓ/ e /ɗ/ que a ortografia latina corrente apenas transcreve como simples b e d. A língua tornou-se mundialmente famosa em 2009, quando Baubau começou a ensiná-la na escrita coreana hangul, ressuscitando jamos obsoletos como ᄫ para a fricativa bilabial que falta ao coreano. Esse projeto sempre foi muito mais pequeno do que a sua fama: o hangul é usado apenas nas escolas e nas placas de rua de umas poucas subdivisões, nunca foi oficialmente adotado, e a esmagadora maioria da escrita em cia-cia continua a ser em alfabeto latino. A maioria dos falantes é bilingue em indonésio e muitos usam também o wólio, língua estreitamente aparentada.",pt_br:"O cia-cia (Bahasa Ciacia, também chamado butão do Sul) é uma língua austronésia do subgrupo muna-butão, falada por cerca de 80.000 a 105.000 pessoas em torno da cidade de Baubau, no sul da ilha de Butão, em Celebes do Sudeste, na Indonésia. Do ponto de vista fonológico é típica da região: cinco vogais, uma oclusiva glotal fonêmica (escrita com apóstrofo, como em ka'ana 'casa' e we'e 'água'), uma série de oclusivas pré-nasalizadas e as implosivas /ɓ/ e /ɗ/ que a ortografia latina comum apenas transcreve como simples b e d. A língua tornou-se mundialmente famosa em 2009, quando Baubau começou a ensiná-la na escrita coreana hangul, ressuscitando jamos obsoletos como ᄫ para a fricativa bilabial que falta ao coreano. Esse projeto sempre foi muito menor do que a sua fama: o hangul é usado apenas nas escolas e nas placas de rua de umas poucas subdivisões, nunca foi oficialmente adotado, e a esmagadora maioria da escrita em cia-cia continua sendo em alfabeto latino. A maioria dos falantes é bilíngue em indonésio e muitos usam também o wólio, língua estreitamente aparentada.",ru:"Чиа-чиа (Bahasa Ciacia, также южнобутонский) — австронезийский язык подгруппы муна-бутон, на котором говорят около 80 000–105 000 человек в окрестностях города Баубау на юге острова Бутон в провинции Юго-Восточный Сулавеси, Индонезия. Фонологически он типичен для региона: пять гласных, фонематическая гортанная смычка (обозначаемая апострофом, как в ka'ana 'дом' и we'e 'вода'), ряд преназализованных смычных и имплозивные /ɓ/ и /ɗ/, которые обычное латинское письмо передаёт лишь как простые b и d. Международную известность язык получил в 2009 году, когда в Баубау начали преподавать его корейским письмом хангыль, возродив вышедшие из употребления чамо, такие как ᄫ, для двугубного фрикативного, которого нет в корейском. Этот проект всегда был куда скромнее своей славы: хангыль используется лишь в школах и на уличных указателях нескольких подрайонов, официально он так и не был принят, и подавляющее большинство текстов на чиа-чиа по-прежнему записывается латиницей. Большинство носителей двуязычны с индонезийским, а многие пользуются также близкородственным языком волио.",uk:"Чіа-чіа (Bahasa Ciacia, також південнобутонська) — австронезійська мова підгрупи муна-бутон, якою розмовляють близько 80 000–105 000 осіб в околицях міста Баубау на півдні острова Бутон у провінції Південно-Східний Сулавесі, Індонезія. Фонологічно вона типова для регіону: п’ять голосних, фонематичний гортанний зімкнений (позначається апострофом, як у ka'ana 'дім' і we'e 'вода'), низка преназалізованих зімкнених та імплозивні /ɓ/ і /ɗ/, які звичайне латинське письмо передає лише як прості b і d. Міжнародної слави мова набула 2009 року, коли в Баубау почали викладати її корейським письмом хангиль, відродивши застарілі чамо, як-от ᄫ, для двогубного фрикативного, якого немає в корейській. Цей проєкт завжди був значно скромнішим за свою славу: хангиль використовується лише в школах і на вуличних вказівниках кількох підрайонів, офіційно його так і не запровадили, і переважна більшість текстів чіа-чіа досі записується латиницею. Більшість мовців двомовні з індонезійською, а багато хто послуговується також близькоспорідненою мовою воліо.",ar:"الشيا-شيا (Bahasa Ciacia، وتُعرف أيضًا ببوتون الجنوبية) لغة أسترونيزية من مجموعة مونا-بوتون الفرعية، يتحدث بها نحو 80,000 إلى 105,000 شخص حول مدينة باوباو في جنوب جزيرة بوتون بمقاطعة سولاويسي الجنوبية الشرقية بإندونيسيا. وهي من الناحية الصوتية نموذجية للمنطقة: خمس حركات، ووقفة حنجرية صواتية (تُكتب بفاصلة عليا، كما في ka'ana 'بيت' وwe'e 'ماء')، وسلسلة من الأصوات الانفجارية المسبوقة بأنفية، والصوتان الانحباسيان الداخليان /ɓ/ و/ɗ/ اللذان لا يكتبهما الرسم اللاتيني المعتاد إلا باءً ودالاً بسيطتين. اكتسبت اللغة شهرة عالمية عام 2009 حين بدأت باوباو تُدرّسها بالأبجدية الكورية هانغول، فأحيت حروف جامو المهجورة مثل ᄫ للاحتكاكي الشفوي الذي يفتقر إليه الكورية. غير أن المشروع كان دائمًا أصغر بكثير من شهرته: فالهانغول لا يُستعمل إلا في مدارس بضع نواحٍ فرعية وعلى لافتات شوارعها، ولم يُعتمد رسميًا قط، وما زالت الغالبية الساحقة من كتابات الشيا-شيا باللاتينية. ومعظم المتحدثين ثنائيو اللغة مع الإندونيسية، ويستخدم كثيرون منهم أيضًا لغة ووليو القريبة الصلة.",he:"צ’יאה-צ’יאה (Bahasa Ciacia, ידועה גם כבוטון הדרומית) היא שפה אוסטרונזית מתת-הקבוצה מונה-בוטון, המדוברת בפי כ-80,000 עד 105,000 בני אדם באזור העיר באובאו בדרום האי בוטון שבמחוז סולאווסי הדרום-מזרחית שבאינדונזיה. מבחינה פונולוגית היא טיפוסית לאזור: חמש תנועות, עיצור סותם סדקי פונמי (הנכתב בגרש, כמו ב-ka'ana 'בית' וב-we'e 'מים'), סדרה של עיצורים סותמים קדם-אפיים, והעיצורים האימפלוסיביים /ɓ/ ו-/ɗ/ שהכתיב הלטיני הרגיל מתמלל בפשטות כ-b וכ-d בלבד. השפה זכתה לפרסום עולמי בשנת 2009, כאשר באובאו החלה ללמד אותה בכתב ההאנגול הקוריאני, והחייתה לשם כך ג’אמו מיושנים כגון ᄫ עבור החוכך הדו-שפתי שאין בקוריאנית. הפרויקט הזה תמיד היה קטן בהרבה מן התהילה שלו: ההאנגול משמש רק בבתי הספר ובשלטי הרחוב של כמה תת-מחוזות בודדים, מעולם לא אומץ באופן רשמי, ורובה המכריע של הכתיבה בצ’יאה-צ’יאה עדיין נעשה בכתב הלטיני. רוב הדוברים דו-לשוניים עם אינדונזית, ורבים משתמשים גם בשפת ווליו הקרובה.",sw:"Kicia-Cia (Bahasa Ciacia, pia hujulikana kama Buton Kusini) ni lugha ya Kiaustronesia ya kikundi kidogo cha Muna-Buton, inayozungumzwa na takriban watu 80,000 hadi 105,000 kuzunguka mji wa Baubau kusini mwa Kisiwa cha Buton, katika jimbo la Sulawesi ya Kusini-Mashariki, Indonesia. Kifonolojia ni ya kawaida kwa eneo hili: vokali tano, kizuizi cha koromeo chenye hadhi ya fonimu (huandikwa kwa alama ya kibainishi, kama katika ka'ana 'nyumba' na we'e 'maji'), mfululizo wa vizuizi vinavyotanguliwa na nazali, na vizuizi vya ndani /ɓ/ na /ɗ/ ambavyo maandishi ya kawaida ya Kilatini huviandika kama b na d tu. Lugha hii ilipata umaarufu wa kimataifa mwaka 2009, wakati Baubau ilipoanza kuifundisha kwa hati ya Hangul ya Kikorea, ikihuisha jamo zilizopitwa na wakati kama vile ᄫ kwa ajili ya kikwamizo cha midomo miwili ambacho Kikorea hakina. Mradi huo daima umekuwa mdogo zaidi kuliko umaarufu wake: Hangul hutumika tu katika shule na alama za barabarani za tarafa chache ndogo, haujawahi kupitishwa rasmi, na sehemu kubwa mno ya maandishi ya Cia-Cia bado iko katika hati ya Kilatini. Wazungumzaji wengi ni wa lugha mbili na Kiindonesia na wengi pia hutumia lugha ya Wolio inayohusiana kwa karibu."},
});

